BEGIN TRANSACTION;
CREATE TABLE detection_alerts (
    alert_id INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id TEXT NOT NULL,
    rule_id TEXT NOT NULL,
    rule_name TEXT NOT NULL,
    severity TEXT NOT NULL,
    alert_time TEXT NOT NULL,
    matched_record_id INTEGER,
    entity_host TEXT,
    entity_user TEXT,
    context_json TEXT,
    FOREIGN KEY(rule_id) REFERENCES detection_rules(rule_id)
);
CREATE TABLE detection_rules (
    rule_id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    severity TEXT NOT NULL CHECK(severity IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL', 'INFORMATIONAL')),
    mitre_attack_id TEXT,                   -- e.g. T1059.001
    mitre_tactic TEXT,                      -- e.g. Execution, Defense Evasion
    mitre_technique TEXT,
    description TEXT,
    sql_query TEXT NOT NULL,
    threshold INTEGER DEFAULT 1,
    lifecycle_stage TEXT DEFAULT 'Active',  -- Prototype, Testing, Active, Deprecated
    status TEXT DEFAULT 'ENABLED',          -- ENABLED, DISABLED
    tune_exclusions TEXT                    -- JSON or SQL WHERE clause filter
);
FROM endpoint_process
WHERE LOWER(parent_process_name) IN (''winword.exe'', ''excel.exe'', ''powerpnt.exe'', ''outlook.exe'')
  AND LOWER(process_name) IN (''powershell.exe'', ''pwsh.exe'', ''cmd.exe'')
  AND (command_line REGEXP ''(?i)(downloadstring|downloadfile|iex|invoke-expression|-enc|-encodedcommand)'');',1,'Active','ENABLED','AND user_name NOT IN (''svc_automation'')');
FROM endpoint_process
WHERE (command_line REGEXP ''(?i)(procdump.*-ma.*lsass|comsvcs(\.dll)?.*minidump|rundll32.*comsvcs.*minidump)'')
   OR (LOWER(command_line) LIKE ''%lsass.dmp%'');',1,'Active','ENABLED','AND host_name NOT LIKE ''%-SANDBOX%''');
FROM endpoint_process
WHERE LOWER(process_name) = ''wevtutil.exe''
  AND command_line REGEXP ''(?i)\s+(cl|cleareventlog)\s+(security|system|application)'';',1,'Active','ENABLED','AND user_name NOT LIKE ''svc_installer''');
FROM endpoint_registry
WHERE (target_object LIKE ''%\CurrentVersion\Run%'' OR target_object LIKE ''%\CurrentVersion\RunOnce%'')
  AND details NOT LIKE ''%Google\Chrome%''
  AND details NOT LIKE ''%Microsoft\OneDrive%'';',1,'Active','ENABLED','AND details NOT LIKE ''%Slack.exe%''');
FROM endpoint_process
WHERE LOWER(parent_process_name) IN (''services.exe'', ''spoolsv.exe'')
  AND LOWER(process_name) IN (''cmd.exe'', ''powershell.exe'', ''whoami.exe'', ''net.exe'');',1,'Testing','ENABLED','');
FROM network_dns
WHERE query_length > 25
  AND ENTROPY(query) > 3.6
  AND query NOT LIKE ''%.corp.local''
  AND query NOT LIKE ''%.google.com'';',1,'Active','ENABLED','AND query NOT LIKE ''%.cloudfront.net''');
FROM network_flow
WHERE bytes_sent > 1000000000
  AND IP_IN_CIDR(src_ip, ''10.0.0.0/8'')
  AND NOT IP_IN_CIDR(dest_ip, ''10.0.0.0/8'');',1,'Active','ENABLED','AND dest_port != 873');
FROM identity_auth
WHERE auth_status = ''FAILURE''
GROUP BY src_ip
HAVING COUNT(DISTINCT user_name) >= 4;',1,'Active','ENABLED','AND src_ip NOT IN (''10.0.4.99'')');
FROM identity_auth
WHERE auth_status = ''SUCCESS''
GROUP BY user_name
HAVING COUNT(DISTINCT geo_country) > 1;',1,'Active','ENABLED','AND user_name NOT LIKE ''svc_%''');
FROM identity_cloud_audit
WHERE action IN (''StopLogging'', ''DeleteTrail'', ''UpdateTrail'', ''DeleteFlowLogs'')
  AND status = ''SUCCESS'';',1,'Active','ENABLED','AND actor NOT LIKE ''%Terraform%''');
CREATE TABLE endpoint_file (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT NOT NULL,
    host_name TEXT NOT NULL,
    user_name TEXT NOT NULL,
    process_name TEXT NOT NULL,
    process_id INTEGER,
    target_filename TEXT NOT NULL,
    target_filepath TEXT NOT NULL,
    file_hash_sha256 TEXT,
    action TEXT NOT NULL                    -- CREATE, MODIFY, DELETE, RENAME
);
CREATE TABLE endpoint_network (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT NOT NULL,
    host_name TEXT NOT NULL,
    process_name TEXT NOT NULL,
    process_id INTEGER,
    src_ip TEXT NOT NULL,
    src_port INTEGER NOT NULL,
    dest_ip TEXT NOT NULL,
    dest_port INTEGER NOT NULL,
    protocol TEXT DEFAULT 'TCP',
    direction TEXT DEFAULT 'outbound'      -- inbound, outbound
);
CREATE TABLE endpoint_process (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT NOT NULL,                -- ISO 8601 (YYYY-MM-DDTHH:MM:SSZ)
    host_name TEXT NOT NULL,
    user_name TEXT NOT NULL,
    process_name TEXT NOT NULL,             -- e.g. powershell.exe, cmd.exe
    process_path TEXT NOT NULL,             -- Full path
    process_id INTEGER NOT NULL,            -- PID
    parent_process_id INTEGER NOT NULL,     -- PPID
    parent_process_name TEXT NOT NULL,      -- e.g. explorer.exe, winword.exe
    parent_process_path TEXT,
    command_line TEXT NOT NULL,
    parent_command_line TEXT,
    process_hash_sha256 TEXT,
    integrity_level TEXT DEFAULT 'Medium',  -- Low, Medium, High, System
    is_elevated INTEGER DEFAULT 0           -- 0 = No, 1 = Yes
);
CREATE TABLE endpoint_registry (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT NOT NULL,
    host_name TEXT NOT NULL,
    user_name TEXT,
    process_name TEXT NOT NULL,
    target_object TEXT NOT NULL,            -- e.g. HKLM\Software\Microsoft\Windows\CurrentVersion\Run
    details TEXT,
    event_type TEXT NOT NULL                -- SetInformation, CreateKey, DeleteKey
);
CREATE TABLE identity_auth (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT NOT NULL,
    user_name TEXT NOT NULL,
    user_domain TEXT DEFAULT 'CORP',
    src_ip TEXT NOT NULL,
    logon_type TEXT DEFAULT 'Network',      -- Interactive, Network, RemoteInteractive (RDP)
    auth_status TEXT NOT NULL,              -- SUCCESS, FAILURE
    failure_reason TEXT,                    -- BadPassword, AccountLocked, UserNotFound
    target_service TEXT,                    -- workstation-01, o365, vpn
    mfa_used INTEGER DEFAULT 0,             -- 0 = No, 1 = Yes
    geo_country TEXT DEFAULT 'US',
    user_agent TEXT
);
CREATE TABLE identity_cloud_audit (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT NOT NULL,
    actor TEXT NOT NULL,                    -- IAM user / role / service account
    actor_type TEXT DEFAULT 'IAMUser',
    action TEXT NOT NULL,                   -- e.g. CreateAccessKey, StopLogging, AuthorizeSecurityGroupIngress
    resource_name TEXT,
    resource_type TEXT,
    src_ip TEXT NOT NULL,
    user_agent TEXT,
    status TEXT DEFAULT 'SUCCESS',          -- SUCCESS, AccessDenied, ClientError
    error_code TEXT
);
CREATE TABLE network_dns (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT NOT NULL,
    host_name TEXT,
    src_ip TEXT NOT NULL,
    query TEXT NOT NULL,                    -- Domain requested
    qtype TEXT DEFAULT 'A',                 -- A, AAAA, TXT, MX
    answers TEXT,
    rcode TEXT DEFAULT 'NOERROR',           -- NOERROR, NXDOMAIN, SERVFAIL
    query_length INTEGER GENERATED ALWAYS AS (LENGTH(query)) VIRTUAL
);
CREATE TABLE network_flow (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT NOT NULL,
    src_ip TEXT NOT NULL,
    src_port INTEGER NOT NULL,
    dest_ip TEXT NOT NULL,
    dest_port INTEGER NOT NULL,
    protocol TEXT NOT NULL,                 -- TCP, UDP, ICMP
    bytes_sent INTEGER DEFAULT 0,
    bytes_recv INTEGER DEFAULT 0,
    packets INTEGER DEFAULT 0,
    action TEXT DEFAULT 'ALLOW',            -- ALLOW, BLOCK
    app_proto TEXT,                         -- http, ssl, dns, ssh
    conn_state TEXT                         -- SF, S0, REJ, OTH
);
CREATE TABLE network_http (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT NOT NULL,
    src_ip TEXT NOT NULL,
    dest_ip TEXT NOT NULL,
    method TEXT NOT NULL,                   -- GET, POST, PUT, DELETE
    host TEXT NOT NULL,
    uri TEXT NOT NULL,
    user_agent TEXT,
    status_code INTEGER DEFAULT 200,
    bytes INTEGER DEFAULT 0
);
CREATE TABLE schema_audit_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT NOT NULL,
    operation_type TEXT NOT NULL,           -- RENAME_COLUMN, RENAME_TABLE, NORMALIZE_ECS, NORMALIZE_OCSF
    target_table TEXT NOT NULL,
    old_value TEXT NOT NULL,
    new_value TEXT NOT NULL,
    status TEXT NOT NULL                    -- SUCCESS, FAILED
);
CREATE INDEX idx_ep_proc_time ON endpoint_process(timestamp);
CREATE INDEX idx_ep_proc_host ON endpoint_process(host_name);
CREATE INDEX idx_ep_proc_name ON endpoint_process(process_name);
CREATE INDEX idx_ep_proc_user ON endpoint_process(user_name);
CREATE INDEX idx_ep_proc_parent ON endpoint_process(parent_process_name);
CREATE INDEX idx_ep_file_time ON endpoint_file(timestamp);
CREATE INDEX idx_ep_file_host ON endpoint_file(host_name);
CREATE INDEX idx_ep_file_path ON endpoint_file(target_filepath);
CREATE INDEX idx_ep_net_time ON endpoint_network(timestamp);
CREATE INDEX idx_ep_net_dest ON endpoint_network(dest_ip, dest_port);
CREATE INDEX idx_ep_reg_time ON endpoint_registry(timestamp);
CREATE INDEX idx_ep_reg_target ON endpoint_registry(target_object);
CREATE INDEX idx_net_flow_time ON network_flow(timestamp);
CREATE INDEX idx_net_flow_src ON network_flow(src_ip);
CREATE INDEX idx_net_flow_dest ON network_flow(dest_ip, dest_port);
CREATE INDEX idx_net_dns_time ON network_dns(timestamp);
CREATE INDEX idx_net_dns_query ON network_dns(query);
CREATE INDEX idx_net_http_time ON network_http(timestamp);
CREATE INDEX idx_net_http_host ON network_http(host);
CREATE INDEX idx_id_auth_time ON identity_auth(timestamp);
CREATE INDEX idx_id_auth_user ON identity_auth(user_name);
CREATE INDEX idx_id_auth_status ON identity_auth(auth_status);
CREATE INDEX idx_id_auth_ip ON identity_auth(src_ip);
CREATE INDEX idx_cloud_time ON identity_cloud_audit(timestamp);
CREATE INDEX idx_cloud_actor ON identity_cloud_audit(actor);
CREATE INDEX idx_cloud_action ON identity_cloud_audit(action);
CREATE INDEX idx_alert_run ON detection_alerts(run_id);
CREATE INDEX idx_alert_rule ON detection_alerts(rule_id);
CREATE INDEX idx_alert_time ON detection_alerts(alert_time);
DELETE FROM "sqlite_sequence";
COMMIT;
