INSERT INTO "detection_rules" VALUES('DET-EP-001','PowerShell Download Cradle Spawned by Office Application','CRITICAL','T1059.001','Execution','Command and Scripting Interpreter: PowerShell','Detects Microsoft Office processes (Word, Excel) spawning PowerShell with download cradles (IEX, WebClient) or bypass flags.','SELECT id, timestamp, host_name, user_name, process_name, parent_process_name, command_line
INSERT INTO "detection_rules" VALUES('DET-EP-002','LSASS Memory Dumping via Procdump or Comsvcs','CRITICAL','T1003.001','Credential Access','OS Credential Dumping: LSASS Memory','Detects command lines indicating dumping of Local Security Authority Subsystem Service (LSASS) memory to disk.','SELECT id, timestamp, host_name, user_name, process_name, command_line
INSERT INTO "detection_rules" VALUES('DET-EP-003','Security Event Log Cleared via Wevtutil','HIGH','T1070.001','Defense Evasion','Indicator Removal: Clear Windows Event Logs','Detects execution of wevtutil.exe to clear the Security or System event logs, often used by attackers to hide tracks.','SELECT id, timestamp, host_name, user_name, process_name, command_line
INSERT INTO "detection_rules" VALUES('DET-EP-004','Persistence via Windows Registry Run Keys','HIGH','T1547.001','Persistence','Boot or Logon Autostart Execution: Registry Run Keys','Detects modifications to Windows Run or RunOnce keys commonly abused to maintain persistence across reboots.','SELECT id, timestamp, host_name, user_name, process_name, target_object, details
INSERT INTO "detection_rules" VALUES('DET-EP-005','Process Tree Anomaly: Suspicious Child Processes of System Daemons','MEDIUM','T1059.003','Execution','Command and Scripting Interpreter: Windows Command Shell','Detects interactive command shells spawned directly by background Windows services (services.exe, svchost.exe).','SELECT id, timestamp, host_name, user_name, process_name, parent_process_name, command_line
INSERT INTO "detection_rules" VALUES('DET-NET-001','DNS Tunneling & DGA via High Shannon Entropy Queries','HIGH','T1071.004','Command and Control','Application Layer Protocol: DNS','Detects DNS queries with high Shannon entropy (score > 3.6) and length > 25 characters, characteristic of DNS tunneling and DGAs.','SELECT id, timestamp, host_name, src_ip, query, query_length, ENTROPY(query) AS entropy_score
INSERT INTO "detection_rules" VALUES('DET-NET-002','Data Exfiltration via Massive Outbound Flow','HIGH','T1048','Exfiltration','Exfiltration Over Alternative Protocol','Detects outbound network flows exceeding 1 GB from internal subnets to external non-RFC1918 addresses.','SELECT id, timestamp, src_ip, dest_ip, dest_port, protocol, bytes_sent, ROUND(bytes_sent / 1073741824.0, 2) AS gb_sent
INSERT INTO "detection_rules" VALUES('DET-ID-001','Password Spraying: Multiple Accounts Failed from Same Source IP','HIGH','T1110.003','Credential Access','Brute Force: Password Spraying','Detects single source IPs generating authentication failures across 5 or more distinct user accounts.','SELECT src_ip, COUNT(DISTINCT user_name) AS targeted_users, COUNT(*) AS failure_count, GROUP_CONCAT(DISTINCT user_name) AS user_list, MIN(timestamp) AS start_time, MAX(timestamp) AS end_time
INSERT INTO "detection_rules" VALUES('DET-ID-002','Impossible Travel: User Authenticating from Multiple Countries','HIGH','T1078','Defense Evasion','Valid Accounts','Detects single user accounts successfully logging in from two different countries within the dataset timeframe.','SELECT user_name, COUNT(DISTINCT geo_country) AS country_count, GROUP_CONCAT(DISTINCT geo_country) AS countries, GROUP_CONCAT(DISTINCT src_ip) AS ips, MIN(timestamp) AS first_seen, MAX(timestamp) AS last_seen
INSERT INTO "detection_rules" VALUES('DET-ID-003','CloudTrail Tampering: StopLogging / DeleteTrail Action','CRITICAL','T1562.001','Defense Evasion','Impair Defenses: Disable Cloud Logs','Detects cloud audit events where an actor attempts to stop logging or delete security audit trails.','SELECT id, timestamp, actor, action, resource_name, src_ip, status
